PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, recovery_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'ALUNO' CHECK(role IN ('ALUNO','PROFESSOR','RECEPCIONISTA','GERENTE','ADMIN')), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profiles(user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, birth_date TEXT, sex TEXT, height REAL, weight REAL, level TEXT DEFAULT 'Iniciante', goal TEXT DEFAULT 'Saúde', avatar TEXT, consent INTEGER NOT NULL DEFAULT 1, consent_at TEXT, preferences TEXT NOT NULL DEFAULT '{}', nutrition_goals TEXT NOT NULL DEFAULT '{"calories":2500,"protein":180,"carbs":280,"fat":70,"water":3000}', professional TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS auth_sessions(token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf TEXT NOT NULL, expires_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS gyms(id INTEGER PRIMARY KEY, name TEXT NOT NULL, address TEXT NOT NULL, hours TEXT NOT NULL, phone TEXT, services TEXT, equipment TEXT);
CREATE TABLE IF NOT EXISTS plans(id INTEGER PRIMARY KEY, name TEXT NOT NULL, price REAL NOT NULL CHECK(price>=0), benefits TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memberships(user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, plan_id INTEGER REFERENCES plans(id), gym_id INTEGER REFERENCES gyms(id), status TEXT NOT NULL DEFAULT 'Ativo', next_billing TEXT, payment_method TEXT DEFAULT 'Pix (demonstração)', cancel_requested INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, amount REAL NOT NULL, due_date TEXT NOT NULL, paid_at TEXT, status TEXT NOT NULL DEFAULT 'Pendente', simulated INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS trainer_students(trainer_id INTEGER REFERENCES users(id) ON DELETE CASCADE, student_id INTEGER REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY(trainer_id,student_id));
CREATE TABLE IF NOT EXISTS exercises(id INTEGER PRIMARY KEY, name TEXT NOT NULL, muscle TEXT NOT NULL, equipment TEXT NOT NULL, instructions TEXT NOT NULL, tip TEXT NOT NULL, mistake TEXT NOT NULL, animation TEXT NOT NULL DEFAULT 'press');
CREATE TABLE IF NOT EXISTS favorites(user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, exercise_id INTEGER REFERENCES exercises(id) ON DELETE CASCADE, PRIMARY KEY(user_id,exercise_id));
CREATE TABLE IF NOT EXISTS workouts(id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, creator_id INTEGER REFERENCES users(id) ON DELETE SET NULL, name TEXT NOT NULL, muscle TEXT NOT NULL, duration INTEGER DEFAULT 60, level TEXT DEFAULT 'Intermediário', day INTEGER DEFAULT 0, notes TEXT DEFAULT '', is_template INTEGER DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workout_exercises(id INTEGER PRIMARY KEY, workout_id INTEGER NOT NULL REFERENCES workouts(id) ON DELETE CASCADE, exercise_id INTEGER NOT NULL REFERENCES exercises(id), position INTEGER NOT NULL, sets INTEGER NOT NULL, reps INTEGER NOT NULL, weight REAL NOT NULL, rest INTEGER NOT NULL, technique TEXT DEFAULT 'Tradicional', notes TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS workout_sessions(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, workout_id INTEGER REFERENCES workouts(id) ON DELETE SET NULL, name TEXT NOT NULL, started_at TEXT NOT NULL, ended_at TEXT, duration INTEGER NOT NULL DEFAULT 0, difficulty TEXT, notes TEXT DEFAULT '', status TEXT NOT NULL DEFAULT 'active', snapshot TEXT NOT NULL DEFAULT '[]', rest_until REAL NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_workout ON workout_sessions(user_id) WHERE status='active';
CREATE TABLE IF NOT EXISTS exercise_sets(id INTEGER PRIMARY KEY, session_id INTEGER NOT NULL REFERENCES workout_sessions(id) ON DELETE CASCADE, exercise_id INTEGER REFERENCES exercises(id), exercise_key TEXT NOT NULL, position INTEGER NOT NULL, weight REAL NOT NULL CHECK(weight>=0), reps INTEGER NOT NULL CHECK(reps>0), done INTEGER NOT NULL DEFAULT 0, UNIQUE(session_id,exercise_key,position));
CREATE TABLE IF NOT EXISTS personal_records(user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, exercise_id INTEGER REFERENCES exercises(id), weight REAL NOT NULL, session_id INTEGER REFERENCES workout_sessions(id) ON DELETE CASCADE, achieved_at TEXT NOT NULL, PRIMARY KEY(user_id,exercise_id));
CREATE TABLE IF NOT EXISTS measurements(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, date TEXT NOT NULL, weight REAL, height REAL, fat REAL, arm REAL, forearm REAL, chest REAL, waist REAL, abdomen REAL, hip REAL, thigh REAL, calf REAL, notes TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS progress_photos(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, date TEXT NOT NULL, angle TEXT NOT NULL, image TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS classes(id INTEGER PRIMARY KEY, title TEXT NOT NULL, teacher TEXT NOT NULL, starts_at TEXT NOT NULL, duration INTEGER NOT NULL, capacity INTEGER NOT NULL, gym_id INTEGER REFERENCES gyms(id), cancel_minutes INTEGER DEFAULT 60);
CREATE TABLE IF NOT EXISTS class_reservations(id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, class_id INTEGER REFERENCES classes(id) ON DELETE CASCADE, created_at TEXT NOT NULL, UNIQUE(user_id,class_id));
CREATE TABLE IF NOT EXISTS calendar_events(id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, kind TEXT NOT NULL, starts_at TEXT NOT NULL, notes TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS access_tokens(token_hash TEXT PRIMARY KEY, user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, expires_at REAL NOT NULL, consumed INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS checkins(id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, gym_id INTEGER REFERENCES gyms(id), created_at TEXT NOT NULL, simulated INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, kind TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, read INTEGER DEFAULT 0, created_at TEXT NOT NULL, event_key TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS achievements(id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL, threshold INTEGER NOT NULL, metric TEXT NOT NULL, xp INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS user_achievements(user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, achievement_id TEXT REFERENCES achievements(id), unlocked_at TEXT NOT NULL, PRIMARY KEY(user_id,achievement_id));
CREATE TABLE IF NOT EXISTS challenges(id TEXT PRIMARY KEY, title TEXT NOT NULL, target INTEGER NOT NULL, metric TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS nutrition_logs(id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, date TEXT NOT NULL, meal TEXT NOT NULL, food TEXT NOT NULL, calories REAL DEFAULT 0, protein REAL DEFAULT 0, carbs REAL DEFAULT 0, fat REAL DEFAULT 0, water REAL DEFAULT 0);
CREATE TABLE IF NOT EXISTS trainer_notes(id INTEGER PRIMARY KEY, trainer_id INTEGER REFERENCES users(id) ON DELETE SET NULL, student_id INTEGER REFERENCES users(id) ON DELETE CASCADE, body TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY, actor_id INTEGER REFERENCES users(id) ON DELETE SET NULL, action TEXT NOT NULL, target_type TEXT NOT NULL, target_id INTEGER, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_user_date ON workout_sessions(user_id,started_at);
CREATE INDEX IF NOT EXISTS measurements_user_date ON measurements(user_id,date);
CREATE INDEX IF NOT EXISTS payments_user_status ON payments(user_id,status);
CREATE INDEX IF NOT EXISTS classes_date ON classes(starts_at);
CREATE INDEX IF NOT EXISTS checkins_user_date ON checkins(user_id,created_at);
CREATE INDEX IF NOT EXISTS notifications_user ON notifications(user_id,read);
CREATE INDEX IF NOT EXISTS nutrition_user_date ON nutrition_logs(user_id,date);
